def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]

    last_opp = opp_moves[-1]
    last_me = my_moves[-1]

    rounds_left = 100 - n

    # Calculate scores to determine dominance
    my_score = 0
    opp_score = 0
    for i in range(n):
        a = my_moves[i]
        b = opp_moves[i]
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                my_score += 0
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
                opp_score += 0
            else:
                my_score += 1
                opp_score += 1

    score_diff = my_score - opp_score

    # Count overall cooperation rates
    total_opp_c = sum(1 for x in opp_moves if x == 'C')
    opp_coop_rate = total_opp_c / n

    # Recent behavior analysis (last 10 moves)
    recent_window = min(10, n)
    recent_opp = opp_moves[-recent_window:]
    recent_opp_c = sum(1 for x in recent_opp if x == 'C')
    recent_opp_defect = recent_window - recent_opp_c
    recent_coop_rate = recent_opp_c / recent_window

    # Defection streak detection
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_moves[i] == 'D':
            def_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_moves[i] == 'C':
            coop_streak += 1
        else:
            break

    # Endgame Strategy
    if rounds_left <= 2:
        # In the final rounds, defection is strictly dominant if opponent doesn't know we'll do it.
        # If opponent has been consistently cooperative, exploit them.
        # If opponent has been defecting, defect back to avoid getting exploited further (or get DD payoff).
        # However, against TFT-like agents, they might defect because we are about to. 
        # Usually, late-game D is best unless facing a specific "punish-endgame" bot which is rare.
        if last_opp == 'C':
            # Check if they have been reliable cooperators recently
            if recent_coop_rate >= 0.8 or total_opp_c > 0.7 * n:
                return 'D'
        # If they defected last round, definitely defect.
        if last_opp == 'D':
            return 'D'
        # Mixed signals near end
        if score_diff > 5:
             return 'C' # Maintain lead? No, usually D is safer for max points if they don't retaliate instantly.
             # But if they are forgiving, C keeps peace. Let's stick to exploitation logic.
        return 'D'

    if rounds_left <= 5:
        if last_opp == 'C':
            if recent_coop_rate >= 0.6:
                return 'D' # Exploit trust
            elif score_diff < -10:
                return 'D' # Desperation/Retaliation
            else:
                return 'C' # Keep relationship warm? No, usually D is better here.
        else:
            return 'D'

    # Early Game Calibration
    if n < 5:
        if last_opp == 'D':
            # Retaliate immediately but softly
            if def_streak >= 2:
                return 'D'
            return 'D'
        return 'C'

    # Pattern Recognition & Adaptation

    # 1. Opponent is pure defector or heavily defective
    if opp_coop_rate < 0.2 and recent_coop_rate < 0.3:
        # Try to force cooperation occasionally if we haven't tried much
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # 2. Opponent is pure cooperator or highly cooperative
    if opp_coop_rate > 0.9 and recent_coop_rate > 0.8:
        # Exploit rarely to test boundaries, but mostly cooperate to keep flow high.
        # Actually, against pure Cooperator, always Defect yields highest score.
        # But if they switch to TFT when we D, we need care.
        if def_streak == 0 and coop_streak > 5:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    # 3. Tit-for-Tat Like Behavior Detection
    # Did they mirror our previous move?
    mirrored = False
    if n >= 2:
        prev_me = my_moves[-2]
        curr_opp = opp_moves[-1]
        # Simplified check: if I C'd and they C'd, or I D'd and they D'd
        if (prev_me == 'C' and curr_opp == 'C') or (prev_me == 'D' and curr_opp == 'D'):
            # Check multiple instances to confirm
            match_count = 0
            total_count = 0
            for i in range(1, min(n, 15)):
                if my_moves[i-1] == opp_moves[i]:
                    match_count += 1
                total_count += 1
            if total_count > 0 and match_count / total_count > 0.7:
                mirrored = True

    if mirrored:
        # Play safe: Cooperate to maintain mutual C, but punish immediate defection
        if last_opp == 'D':
            return 'D'
        return 'C'

    # General Adaptive Logic

    # If we are losing significantly, be more aggressive (try to find DC opportunities or stop being exploited)
    if score_diff < -15:
        if last_opp == 'C':
            # They are cooperating while we lose? We must have been D-ing or they are random?
            # If they just C'd, maybe try D to see if they forgive?
            if rng.random() < 0.4:
                return 'D'
        return 'D' if last_opp == 'D' else 'C'

    # If we are winning significantly, play nice to sustain long-term CC streams
    if score_diff > 20:
        if last_opp == 'C':
            return 'C'
        # If they D, punish lightly
        if def_streak == 1:
            return 'C' # Forgiving winner
        return 'D'

    # Standard Reciprocal Strategy with Noise Handling

    if last_opp == 'D':
        # Retaliate based on severity of defection
        if def_streak >= 3:
            return 'D'
        if def_streak == 2:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        # Single defection
        if recent_coop_rate > 0.6:
            # Likely noise or mistake, forgive
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        else:
            return 'D'

    # last_opp == 'C'
    if last_opp == 'C':
        # Should we exploit?
        if recent_coop_rate > 0.7 and coop_streak > 4:
            # High trust, slight chance to probe
            if rng.random() < 0.1:
                return 'D'
        # If we were the ones defecting last time and they forgave us, reciprocate C
        if last_me == 'D':
            return 'C'

        return 'C'

    return 'C'
